pub fn greater(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    debug_assert_eq!(a.len(), b.len(), "inputs must have the same length");

    a.into_iter()
        .zip(b.into_iter())
        .map(|(x, y)| (x as i32) > (y as i32))
        .collect()
}